package com.bonbio.controller;
import com.bonbio.dto.Dtos.*; import com.bonbio.service.CommandeService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/commandes") public class CommandeController {private final CommandeService s; public CommandeController(CommandeService s){this.s=s;} @GetMapping public List<CommandeResponse> all(){return s.all();} @GetMapping("/{id}") public CommandeResponse one(@PathVariable Long id){return s.one(id);} @PostMapping public CommandeResponse add(@Valid @RequestBody CommandeRequest r){return s.save(null,r);} @PutMapping("/{id}") public CommandeResponse edit(@PathVariable Long id,@Valid @RequestBody CommandeRequest r){return s.save(id,r);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);} }
